import traceback

import numpy as np


class TestManager:
    """
    Class to manage the registration of test scores.
    """

    def __init__(self, test_scores):
        """
        Initialize with a reference to the dictionary where scores will be stored.
        """
        self.test_scores = test_scores

    def register_test(func):
        """
        Decorator to register a test as executed.

        A test that raises scores 0 and the traceback is printed, rather than the whole
        test file stopping. That is deliberate: your unfinished tasks should not hide the
        score of the ones you have finished.
        """
        def wrapper(self, *args, **kwargs):
            try:
                result = func(self, *args, **kwargs)
                self.test_scores[func.__name__] = result
                return result
            except (AssertionError, Exception) as e:
                error_type = "AssertionError" if isinstance(e, AssertionError) else "Exception"
                print(f"Test {func.__name__} failed with {error_type}...")
                print(traceback.format_exc())
                print(50 * "-")
                self.test_scores[func.__name__] = 0
                return 0
        return wrapper


def rel_error(x, y):
    """ Returns the relative error between two arrays. """
    return np.max(np.abs(x - y) / (np.maximum(1e-8, np.abs(x) + np.abs(y))))


def eval_numerical_gradient(f, x, verbose=True, h=0.00001):
    """
    A naive implementation of the numerical gradient of f at x.

    :param f: function that takes a single argument.
    :param x: point (numpy array) to evaluate the gradient at.
    :param verbose: print each partial derivative as it is computed.
    :param h: step size of the centered difference.

    :return: the gradient, same shape as x.
    """
    grad = np.zeros_like(x)
    it = np.nditer(x, flags=['multi_index'], op_flags=['readwrite'])
    while not it.finished:
        ix = it.multi_index
        oldval = x[ix]

        x[ix] = oldval + h
        fxph = f(x)
        x[ix] = oldval - h
        fxmh = f(x)
        x[ix] = oldval

        grad[ix] = (fxph - fxmh) / (2 * h)
        if verbose:
            print(ix, grad[ix])
        it.iternext()

    return grad


def eval_numerical_gradient_array(f, x, df, h=1e-5):
    """
    Evaluate a numeric gradient for a function that takes a numpy array and returns one.

    :param f: function from array to array.
    :param x: point to evaluate the gradient at.
    :param df: upstream gradient.
    :param h: step size of the centered difference.

    :return: the gradient, same shape as x.
    """
    grad = np.zeros_like(x)
    it = np.nditer(x, flags=['multi_index'], op_flags=['readwrite'])
    while not it.finished:
        ix = it.multi_index
        oldval = x[ix]

        x[ix] = oldval + h
        pos = f(x)
        x[ix] = oldval - h
        neg = f(x)
        x[ix] = oldval

        grad[ix] = np.sum((pos - neg) * df) / (2 * h)
        it.iternext()

    return grad
